		public ZString GetShortDescription(ZString errorCode)
		{
			ZString result;

			if (inBondCommonErrors.TryGetValue(errorCode, out result))
			{
				result = result.Split('|')[0];
			}

			return result;
		}

		public ZString GetLongDescription(ZString errorCode)
		{
			ZString result;

			if (inBondCommonErrors.TryGetValue(errorCode, out result))
			{
				result = result.Split('|')[1];
			}

			return result;
		}

		public ZString GetMessageTextFromDescription(ZString errorDescription)
		{
			var result = errorDescription;
			var errorCode = inBondCommonErrors.Where(x => GetShortDescription(x.Key).ToUpper() == errorDescription.ToUpper()).Select(x => x.Key).FirstOrDefault();
			if (!errorCode.IsEmpty)
			{
				result = errorDescription + "<p />" + GetLongDescription(errorCode);
			}
			return result;
		}
	}
